74	/** Assign a status list index to a new credential. Returns { listId, statusIndex }. */
75	export function assignStatusIndex(credentialId: string, holderEmail: string): { listId: string; statusIndex: number } {
76	  const store = loadStore();
77	  if (store.nextIndex >= LIST_SIZE) throw new Error('StatusList full — create a new list');
78	
79	  const statusIndex = store.nextIndex++;
80	  store.issuedCredentials.push({
81	    credentialId,
82	    holderEmail,
83	    statusIndex,
84	    issuedAt: new Date().toISOString(),
85	    revoked: false,
86	  });
87	  saveStore(store);
88	  return { listId: store.listId, statusIndex };
89	}
90	
91	/** Revoke a credential by ID. Returns true if found and revoked. */
92	export function revokeCredential(credentialId: string, reason: string = 'Administrative Revocation'): boolean {
93	  const store = loadStore();
94	  const entry = store.issuedCredentials.find(c => c.credentialId === credentialId);
95	  if (!entry || entry.revoked) return false;
96	
97	  const revokedAt = new Date().toISOString();
98	  entry.revoked = true;
99	  entry.revokedAt = revokedAt;
100	  
101	  // Only add to revokedIndices if not already there
102	  if (!store.revokedIndices.includes(entry.statusIndex)) {
103	    store.revokedIndices.push(entry.statusIndex);
104	  }
105	  saveStore(store);
106	
107	  // Invalidate cache to force re-signing on next request
108	  cachedStatusListJWT = null;
109	
110	  // Audit logging (simulated as console log, could be a separate file/DB)
111	  console.log(`[audit] REVOKE: Credential ${credentialId} (Index ${entry.statusIndex}) revoked at ${revokedAt}. Reason: ${reason}`);
112	
113	  return true;
114	}
