151	/** Get credential by ID. */
152	export function getCredentialById(credentialId: string) {
153	  const store = loadStore();
154	  return store.issuedCredentials.find(c => c.credentialId === credentialId);
155	}
156	
157	/** Get the current list ID. */
158	export function getListId(): string {
159	  return loadStore().listId;
160	}
161	
162	/** Build and sign a StatusList2021 VC. Served at /status/{listId}. */
163	export async function buildStatusListJWT(): Promise<string> {
164	  const store = loadStore();
165	  const { privateKey, kid } = await getIssuerKeyPair();
166	  const config = loadConfig();
167	
168	  const bitstring = buildBitstring(store.revokedIndices);
169	  const now = Math.floor(Date.now() / 1000);
170	
171	  const revokedIndicesHash = store.revokedIndices.sort((a, b) => a - b).join(',');
172	  
173	  // Check cache validity
174	  if (cachedStatusListJWT && 
175	      cachedStatusListJWT.revokedIndicesHash === revokedIndicesHash &&
176	      Date.now() - cachedStatusListJWT.timestamp < STATUSLIST_CACHE_TTL_MS) {
177	    return cachedStatusListJWT.jwt;
178	  }
179	
180	  const jwt = await new SignJWT({
181	    '@context': ['https://www.w3.org/2018/credentials/v1', 'https://w3id.org/vc/status-list/2021/v1'],
182	    type: ['VerifiableCredential', 'StatusList2021Credential'],
183	    issuer: config.issuer.did,
184	    issuedAt: new Date().toISOString(),
185	    credentialSubject: {
186	      id: `${config.issuer.url}/status/${store.listId}`,
187	      type: 'StatusList2021',
188	      statusPurpose: 'revocation',
189	      encodedList: bitstring,
190	    },
191	  })
192	    .setProtectedHeader({ alg: 'ES256', kid, typ: 'JWT' })
193	    .setIssuedAt(now)
194	    .sign(privateKey);
195	
196	  // Cache the signed JWT
197	  cachedStatusListJWT = {
198	    jwt,
199	    revokedIndicesHash,
200	    timestamp: Date.now()
201	  };
202	
203	  return jwt;
204	}
